from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            if target == 0:
                return True

            N = [(target + p - 1) // p for p in points]

            # E_prime[i] represents the number of right-to-left transitions from i+1 to i
            # Computed assuming we end at node n-1
            E_prime = [0] * (n - 1)
            prev = 0
            sum_E = 0

            for i in range(n - 1):
                if i == n - 2:
                    val = max(0, N[i] - 1 - prev, N[i + 1] - 1)
                else:
                    val = max(0, N[i] - 1 - prev)
                E_prime[i] = val
                sum_E += val
                prev = val

            # Find the optimal ending node by checking the rightmost index that violates 
            # the stronger constraints of ending at an earlier node.
            j_viol = 0
            for j in range(n - 1, 0, -1):
                if j == n - 1:
                    if E_prime[n - 2] < N[n - 1]:
                        j_viol = n - 1
                        break
                else:
                    if E_prime[j] < 1 or E_prime[j - 1] + E_prime[j] < N[j]:
                        j_viol = j
                        break

            min_moves = 1 + j_viol + 2 * sum_E
            return min_moves <= m

        left, right = 0, min(points) * ((m + 1) // 2 + 1)

        while left < right:
            mid = (left + right + 1) // 2
            if can(mid):
                left = mid
            else:
                right = mid - 1

        return left
